class Solution {
public:
    long long maxStrength(vector<int>& nums) {
        if (nums.size() == 1) return nums[0];
        vector<int> pos, neg;
        bool has_zero = false;
        for (int x : nums) {
            if (x > 0) pos.push_back(x);
            else if (x < 0) neg.push_back(x);
            else has_zero = true;
        }
        sort(neg.begin(), neg.end());
        if (neg.size() % 2 == 1) neg.pop_back();
        if (pos.empty() && neg.empty()) return 0;
        long long prod = 1;
        for (int x : pos) prod *= x;
        for (int x : neg) prod *= x;
        return prod;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public long maxStrength(int[] nums) {
        if (nums.length == 1) return nums[0];
        List<Integer> pos = new ArrayList<>();
        List<Integer> neg = new ArrayList<>();
        for (int x : nums) {
            if (x > 0) pos.add(x);
            else if (x < 0) neg.add(x);
        }
        Collections.sort(neg);
        if (neg.size() % 2 == 1) neg.remove(neg.size() - 1);
        if (pos.isEmpty() && neg.isEmpty()) return 0;
        long prod = 1;
        for (int x : pos) prod *= x;
        for (int x : neg) prod *= x;
        return prod;
    }
}

var maxStrength = function(nums) {
    if (nums.length === 1) return nums[0];
    const pos = [];
    const neg = [];
    for (const x of nums) {
        if (x > 0) pos.push(BigInt(x));
        else if (x < 0) neg.push(BigInt(x));
    }
    neg.sort((a, b) => (a < b ? -1 : 1));
    if (neg.length % 2 === 1) neg.pop();
    if (pos.length === 0 && neg.length === 0) return 0;
    let prod = 1n;
    for (const x of pos) prod *= x;
    for (const x of neg) prod *= x;
    return Number(prod);
};
